 function categorical_hideDKREF_page(el) {

  if (IntMode !== 'CAWI') return;

  const $question = $(el);
  const exclusivecodesLength = $question.find('.exclusivecodes').length;

  // initial hide
  if (
    $question.find('.cf-radio--selected').length === 0 &&
    $question.find('.cf-checkbox--selected').length === 0 &&
    $question.find('.cf-error-list__item').length === 0 &&
    exclusivecodesLength > 0
  ) {
    $question
      .find('.cf-list__item')
      .has('.exclusivecodes')
      .hide();
  }

   $('.cf-navigation')
    .off(`click.dkref.${$question.attr('id')}`) // prevent override across questions
    .on(`click.dkref.${$question.attr('id')}`, function () {

      if ($question.find('.cf-error-list__item').length > 0) {

        $question.find('.cf-list__item').show();

        $question.find('.cf-error-list__item').each(function () {
          if ($(this).text().trim().includes('Please select an answer')) {
            $(this).text(
              'You have not provided a response. Is that because you’re not sure, or you would prefer not to answer?'
            );
          }
        });

      }

    });
}

