/* 4/6/26 - added in by Erika syntax copied from another Lina job 3522L the hovering part */

 a {
 	color: #224F77;
 }


 a.info {
 	position: relative;
 	/*this is the key*/
 	z-index: 24;
 	color: #000;
 	text-decoration: underline;
 }



 a.info:hover {
 	z-index: 25;
 }



 a.info span {
 	display: none
 }



 a.info:hover span {
 	/*the span will display just on :hover state*/
 	display: block;
 	position: absolute;
 	top: 2em;
 	left: 2em;
 	width: 30em;
 	border: 1px solid #0cf;
 	background-color: #cff;
 	color: #007DC4;
 	text-align: left;
 	padding-top: 0px;
 	padding-left: 3px;
 	padding-right: 3px;
 	padding-bottom: 3px;
 	font-weight: normal;
 	text-decoration: none;
 }

 .tooltip_src {
 	position: relative;
 	display: inline;
 	border-bottom: 2px dotted black;
	cursor: help; 

 }



 .tooltip_src .tooltiptext {
 	visibility: hidden;
 	width: 240px;
 	background-color: black;
 	color: #fff;
 	text-align: left;
 	border-radius: 6px;
 	padding: 5px 5px;
 	padding-left: 20px;
 	/* Position the tooltip */
 	position: absolute;
 	z-index: 1;
 	text-indent: 0px
 }



 .tooltip_src:hover .tooltiptext {
 	visibility: visible;
 }

