let Questionname= $(".cf-question.cf-question--numeric-list").attr("id")
QuestionContentDiv.find(".cf-grid-layout").append("<div class= 'cf-grid-layout__row cf-numeric-list-answer'><div class='cf-grid-layout__row-text'></div>Total:<span class='sum_total' ></span></div>")
var Sumtotal;
QuestionContentDiv.find("input[type=number]").on('input keyup',function () {

    SumAll();
})


 function SumAll(){
    let total=0
	QuestionContentDiv.find('.cf-numeric-list-answer__input').each(function() {					 
					val = $(this).val();
					if(isNaN(parseFloat(val))) {
						total += 0;
					} else {
						total += parseFloat(val)
					}
				});
				$('.sum_total').text(total.toFixed(2)); 				 
 }

