Grid3D.StartupScript:
document.querySelector('option').textContent = "Please select";

$(function(){

bindAutosum("#QN4a3D");
    // --- helpers ---
    function getRowCodeFromId(id) {
        // desktop: desktop_QN4aN_1
        // mobile : mobile_QN4aN_1_input
        var parts = String(id || "").split("_");
        if (!parts.length) return null;

        var last = parts[parts.length - 1];
        if (last === "input") return parts[parts.length - 2] || null; // mobile
        if (last === "autosum") return null;
        return last; // desktop
    }

function isChecked($ctrl) {
    // Forsta checkboxes are often <div role="checkbox" aria-checked="true|false">
    if (!$ctrl || !$ctrl.length) return false;
    return String($ctrl.attr("aria-checked")).toLowerCase() === "true";
  }

  function parseNum(v) {
    if (v === null || v === undefined || v === "") return null;
    var n = Number(v);
    return Number.isFinite(n) ? n : null;
    } 

    function computeTotalHours(qname) {
        var $q = $(qname);
        if (!$q.length) return;

        var totalHours = 0;

        var $nums = $q
            .find('input[type="number"]')
            .filter(function () {
                return this.id &&
                    this.id.indexOf("autosum") === -1 &&
                    $(this).is(":visible");
            });

        $nums.each(function () {
            var id = this.id;
            var code = getRowCodeFromId(id);
            if (!code) return;

            var qid = $q.attr("id");   

             var $dk = $("#desktop_" + qid.replace("3D", "DK") + "_" + code + "_control, #mobile_" + qid.replace("3D", "DK") + "_" + code + "_control");
            var $ref = $("#desktop_" + qid.replace("3D", "REF") + "_" + code + "_control, #mobile_" + qid.replace("3D", "REF") + "_" + code + "_control");

            if (isChecked($dk) || isChecked($ref)) return;

            var rawVal = parseNum($(this).val());
            if (rawVal === null) return;

            var $metric = $("#desktop_" + qid.replace("3D", "hm") + "_" + code + "_input, #mobile_" + qid.replace("3D", "hm") + "_" + code + "_input");
            var metricVal = $metric.length ? String($metric.val() || "") : "";

            if (metricVal === "") return;

            var hours = (metricVal === "2") ? (rawVal / 60) : rawVal;
            totalHours += hours;
        });

        var totalStr = totalHours.toFixed(2);


        $q.find('.cf-numeric-list-auto-sum__value')
            .add($q.find('[id$="_autosum"]'))
            .text(totalStr);
    }
    function bindAutosum(qname) {
        var $q = $(qname);

         computeTotalHours(qname);

         $q.on("input change", 'input[type="number"]', function () {
            computeTotalHours(qname);
        });

        $q.on("change", "select.cf-dropdown", function () {
            computeTotalHours(qname);
        });

        $q.on("click keyup", '[role="checkbox"]', function (e) {
            if (e.type === "keyup" && e.key !== " " && e.key !== "Enter") return;
            computeTotalHours(qname);
        });
    }




    //$('#desktop_QN4aN_autosum').add('.cf-numeric-list-auto-sum__value')

})

